import {SKILLS,elementLabel,WORLD_ITEMS,dungeonElement,ELEMENTS} from './elements.js';
import './style.css';
import './pixel.css';
import './mobile.css';
import { PILL_GRADES,FURNACES,EQUIPMENT,EQUIPMENT_SLOTS,equippedId,equipmentText,WAREHOUSE_CATEGORIES,itemCategory } from './systems.js';
import { initArt, itemIcon, artUrl, objectIcon } from './art.js';
