import { initialState, restoreState, transition, ITEMS, RECIPES, WEAPONS, REALMS, credit, availableCredit, lifeLeft, lifeFactor, maxHP, maxMana, attack, defense, materialCount, materialKeys, capacity, inventoryCount } from './game.js';
import { startBattle } from './battle.js';

const SAVE = 'yilu-chenmeng-v1';
const root = document.querySelector('#app');
let state = load(), page = 'homestead', battle = null, toastTimer;
let selectedDungeon = state.selectedDungeon ?? DUNGEONS[0].id;
let bagSelected=null;
const homeCamera={initialized:false};let disposeHomeCamera=null;
let homeEdit=null,hero={x:7,y:6},walkFrame=null;
let questTab='ongoing';
let shopGrade=0;
let farmPage=0,shopTab='materials',warehouseTab='all',recipeGrade=0;
const number = n => Math.floor(n).toLocaleString('zh-CN');
const poisonBlockedAttr=()=>state.toxin>=100?"disabled title=\"丹毒已满，无法服丹\"":"";
const resourceMeter=(label,value,max,kind)=>{const current=Math.max(0,Math.min(max,Number(value)||0));const pct=max?current/max*100:0;return `<div class="resource-meter ${kind}" aria-label="${label} ${Math.ceil(current)}/${max}"><span class="resource-label">${label}</span><div class="resource-track" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${Math.ceil(current)}"><i style="width:${pct}%"></i></div><b>${Math.ceil(current)}/${max}</b></div>`;};
const cultivationMeter=()=>{const current=Math.max(0,Math.floor(state.cultivation)),fill=Math.min(80,current),label=REALMS[state.realm]+state.level+"级";return `<div class="resource-meter cultivation-meter" aria-label="当前境界 ${label}，修为 ${current}/80"><span class="resource-label">${label}</span><div class="resource-track" role="progressbar" aria-label="修为" aria-valuemin="0" aria-valuemax="80" aria-valuenow="${fill}"><i style="width:${Math.min(100,fill/80*100)}%"></i></div><b>${current}/80</b></div>`;};
const names = ['破旧老屋','整修木屋','乡间小院','修仙宅院'];
const tabs = [['travel','剑','外出'],['homestead','舍','回家'],['person','人','人物']];
function load() {
  try{return restoreState(JSON.parse(localStorage.getItem(SAVE)));}catch{return initialState();}
}
function save() { try { localStorage.setItem(SAVE,JSON.stringify(state)); } catch { toast('存档写入失败，请检查浏览器存储权限。'); } }
function toast(text) {
  let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';el.setAttribute('role','status');document.body.append(el);}
  el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);
}
function act(action,payload={}) {
  try { const before=state;state=transition(state,action,payload);setSound(state.settings.sound);save();render();refreshSceneSheet();playSound(action==='harvest'?'harvest':action==='brew'?(state.lastBrew.success?'brew':'fail'):action==='breakthrough'?'breakthrough':action==='claim-quest'?'reward':'click');
  if(action==='farm-art')toast(FARM_ARTS[payload.item].name+'施展成功');if(action==='breakthrough')toast(REALMS[state.realm]+state.level+'级 · '+(state.realm>before.realm?'新经营能力与材料已解锁':state.realm===0&&state.level===7?'已领悟引露术':'成功率随修为提升'));
  if(['house','furnace'].includes(action))toast(action==='house'?names[before.house]+' → '+names[state.house]:'丹炉 '+PILL_GRADES[before.furnace]+' → '+PILL_GRADES[state.furnace]);
  if(['equip','unequip','weapon'].includes(action))toast('攻击 '+attack(before)+' → '+attack(state)+' · 防御 '+defense(before)+' → '+defense(state)+' · 气血上限 '+maxHP(before)+' → '+maxHP(state));
  if(action==='buy'||action==='market-buy'||action==='claim-quest')toast(action==='claim-quest'?'奖励已领取':'购入成功，请到背包或人物查看');if(action==='brew'&&!state.lastBrew.success)document.querySelector('.game-screen').insertAdjacentHTML('afterbegin',button('返回药田补材料','navigate','data-page="farm"',false,'gold'));if(action==='brew')toast(state.lastBrew.success?'炼丹成功 · 经验+10':'炼丹失败 · 材料作废，可返回药田补充');if(state.journey.chapterComplete&&!before.journey.chapterComplete){toast('第一章完成 · 草庐立足，洗髓丹线索已记入任务');playSound('reward');}else if(state.journey.dewRecipe&&!before.journey.dewRecipe)toast('青岚残卷已发现 · 凝露丹方解锁');return true; } catch(e){toast(e.message);return false;}
}
const button = (text,action,data='',disabled=false,cls='') => `<button class="btn ${cls}" data-action="${action}" ${data} ${disabled?'disabled':''}>${text}</button>`;
function sceneHotspots(){return '<button class="scene-hotspot building-hotspot" style="left:58%;top:14%;width:36%;height:28%" data-action="navigate" data-page="home" aria-label="进入住宅"><span>住宅</span></button><button class="scene-hotspot" style="left:17%;top:64%;width:60%;height:29%" data-action="navigate" data-page="farm" aria-label="进入药田"><span>药田</span></button><button class="scene-hotspot" style="left:80%;top:46%;width:18%;height:18%" data-action="navigate" data-page="alchemy" aria-label="进入炼丹洞"><span>炼丹洞</span></button>';}
const itemTag = k => itemIcon(k)+`<span class="badge">${elementLabel(ITEMS[k])}</span>`;
function scene(interactive=false) {
  return `<div class="pixel-world home-map-viewport"><div class="home-map-layer"><canvas class="world-canvas" aria-label="像素清溪乡：老屋、药田与散修主角"></canvas>${interactive?state.plots.slice(farmPage*4,farmPage*4+4).map((p,slot)=>{
    const i=farmPage*4+slot;const ready=p&&state.day>=p.ready;
    return `<button class="field-hotspot soil-${plotSoil(state,i)} ${ready?'ripe':''}" style="left:${FIELD_LAYOUT[slot][0]/384*100}%;top:${FIELD_LAYOUT[slot][1]/420*100}%;width:${FIELD_WIDTH/384*100}%;height:${FIELD_HEIGHT/420*100}%" data-action="plot" data-index="${i}" aria-label="药田${i+1} · ${p?(ready?'可收获':'生长中'):'空地'}"><span>${p?(ready?'✦':p.ready-state.day+'日'):'＋'}</span></button>`;
  }).join(''):''}${interactive?'':sceneHotspots()}<span class="location-label">清溪乡 · ${names[state.house]}</span><span class="world-hint">${interactive?'点击场景物件 · 进入与操作':'山居草庐'}</span></div></div>`;
}
function heading(eyebrow,title,subtitle,extra='') {return `<div class="section-heading"><div><h2>${title}</h2><p>${subtitle}</p></div>${extra}</div>`;}
function farmPanel() {
  return `<div class="scene-title"><div><span class="eyebrow">第一卷 · 草庐初醒</span><h2>山间药田</h2></div><span class="badge">药田 ${state.plots.length} / ${plotLimit(state)}</span></div>${scene(true)}<div class="field-pager">${button('上一片','plot-page',`data-field-page="${farmPage-1}"`,farmPage===0,'subtle')}<span>第 ${farmPage+1} / ${Math.ceil(state.plots.length/4)} 片</span>${button('下一片','plot-page',`data-field-page="${farmPage+1}"`,farmPage>=Math.ceil(state.plots.length/4)-1,'subtle')}${button('扩建','expand-menu','',false,'gold')}</div><div class="game-toolbar"><div class="bag-slot">${itemIcon('seed')}<span>种子 <b>${state.inventory.seed}</b></span></div><div class="bag-slot">${itemIcon('herb')}<span>仙草 <b>${state.inventory.herb}</b></span></div><div class="bag-slot">${itemIcon('heal')}<span>回春丹 <b>${state.inventory.heal}</b></span></div>${button('休养一日','rest','',false,'gold')}</div>${farmArts()}${productionChoices()}<div class="quest-note"><span class="quest-marker">!</span><div><strong>${state.realm?'归途与远山':'重燃炉火'}</strong><p>${state.realm?'升级住宅可扩建药田，改造土地后可种植特殊仙草。':'点击空药田播种。休息两日收获，交付道友订单，用破败丹炉炼制粗制丹药。'}</p></div></div>`;
}
const gradeBadge=k=>ITEMS[k].grade===undefined?'':`<span class="grade-badge grade-${ITEMS[k].grade}">${PILL_GRADES[ITEMS[k].grade]}</span>`;
function pillDescription(k){const i=ITEMS[k];return i.breakthroughOnly?'炼气十级突破筑基时消耗1颗 · 不可服用或出售':i.manaRestore?'回复'+i.manaRestore+'法力 · 丹毒+'+i.toxin:i.heal?'回复'+i.heal+'气血 · 丹毒+'+i.toxin:i.cultivation?'增加'+i.cultivation+'修为 · 丹毒+'+i.toxin:'永久提升资质 · 不可买卖';}
function productionChoices(){return '<div class="production-preview"><h3>这批仙草怎么用？</h3><p>卖草：青灵草每株'+ITEMS.herb.sell+'灵石，立即回款。</p><p>加工：'+Object.entries(RECIPES).filter(([id,r])=>!ITEMS[id].legacyVariant&&ITEMS[id].grade<=1&&r.materials.herb&&state.realm>=r.realm&&state.furnace>=r.furnace).slice(0,4).map(([id])=>{const e=brewEconomics(state,id,ITEMS,RECIPES,brewChance(state,ITEMS[id].grade));return ITEMS[id].name+'平均加工差额'+(e.margin>=0?'+':'')+e.margin;}).join('；')+'灵石。</p><p>自用：聚气丹换修为；回春、回灵丹留作秘境或仙术补给。丹毒越高，服丹效果越弱。</p><p>订单：'+state.orders.filter(o=>!o.done&&!o.ignored).map(o=>ITEMS[o.item].name+'×'+o.qty+' → '+o.reward+'灵石').join('；')+'。</p>'+button('去炼丹','navigate','data-page="alchemy"')+button('查看订单','navigate','data-page="orders"')+button('背包出售或服丹','navigate','data-page="warehouse"')+'</div>';}
function farmArts(){return '<div class="production-arts">'+Object.entries(FARM_ARTS).map(([id,a])=>'<div><strong>'+a.name+'</strong><p>'+a.text+'</p><small>'+a.mana+'法力 · '+a.energy+'精力 · 不推进日期</small>'+button(artUnlocked(state,id)?'施展':REALMS[a.realm]+a.level+'级解锁','farm-art','data-item="'+id+'"',!artUnlocked(state,id)||state.mana<a.mana||state.energy<a.energy||!state.plots.some(p=>p&&p.ready>state.day&&!p[id]))+'</div>').join('')+'</div>';}
function recipeEconomics(id){const e=brewEconomics(state,id,ITEMS,RECIPES,brewChance(state,ITEMS[id].grade));const orders=state.orders.filter(o=>o.item===id&&!o.done&&!o.ignored);return '<p class="production-preview">材料直售 '+e.direct+'灵石<br>成功出售 '+e.sale+'灵石 · 平均回款约'+e.expected+'<br>平均加工差额 '+(e.margin>=0?'+':'')+e.margin+'灵石（未计精力）'+(orders.length?'<br>当前订单：'+orders[0].qty+'颗换'+orders[0].reward+'灵石':'')+'</p><small>材料按低品质优先消耗；不足部分按基础材料估值。平均值用于比较，仍可能连续失败。</small>';}
function furnacePanel(){const f=FURNACES[state.furnace],next=FURNACES[state.furnace+1];return `<div class="feature-strip"><div class="medallion">炉</div><div><h3>${f.name}</h3><p>可炼${PILL_GRADES[state.furnace]}及以下品质 · 炼丹 ${alchemyLevel(state)}级 · 经验 ${alchemyProgress(state)}${next?`<br>升级需 ${number(f.upgrade)}灵石 · 赤铜矿 ${materialCount(state,'ore')}/${f.ore}份（任意品质）`:``}</p><div class="meter" role="progressbar" aria-label="炼丹经验" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${alchemyLevel(state)>=10?100:alchemyXP(state)%100}"><i style="width:${alchemyLevel(state)>=10?100:alchemyXP(state)%100}%"></i></div></div>${button(next?'升级 · '+number(f.upgrade)+'灵石':'传说级丹炉','furnace','',!next||state.realm<next.realm||state.cash<f.upgrade||materialCount(state,'ore')<f.ore)}</div>`;}
function alchemy(){
  return heading('','丹房 · 六品炉火','卖草换稳定现金，炼丹承担风险赚加工回报，服丹加快修炼。成功经验+10；失败材料作废。')+(state.journey.dewRecipe?'<p class="realm-production-note">青岚残卷已发现：初级凝露丹需月华仙草，可低丹毒修炼。种子需种在灵土。</p>':'')+furnacePanel()+`<div class="panel-tabs">${PILL_GRADES.map((name,i)=>`<button class="tab-btn ${recipeGrade===i?'active':''}" data-action="recipe-grade" data-grade="${i}">${name}</button>`).join('')}</div><div class="cards two">${Object.entries(RECIPES).filter(([k])=>!ITEMS[k].legacyVariant&&ITEMS[k].grade===recipeGrade).map(([k,r])=>`<article class="card"><div class="card-top">${itemTag(k)}${gradeBadge(k)}</div><h3>${ITEMS[k].name}</h3><p>${pillDescription(k)}<br><strong>${state.realm<r.realm?'需'+REALMS[r.realm]+'境界 · ':''}${state.furnace<r.furnace?'需'+PILL_GRADES[r.furnace]+'丹炉 · ':''}成功率 ${brewChance(state,ITEMS[k].grade)}%</strong></p>${recipeEconomics(k)}<div class="recipe">${Object.entries(r.materials).map(([m,q])=>`<span class="${materialCount(state,m)>=q?'ok':''}">${ITEMS[m].name} ${materialCount(state,m)}/${q}</span>`).join('')}</div><div class="card-bottom"><span>${state.furniture.table?12:18}精力</span>${button(r.discovery&&!state.journey.dewRecipe?'青岚残卷未发现':'炼制','brew',`data-item="${k}"`,r.discovery&&!state.journey.dewRecipe||state.realm<r.realm||state.furnace<r.furnace||state.energy<(state.furniture.table?12:18)||Object.entries(r.materials).some(([m,q])=>materialCount(state,m)<q))}</div></article>`).join('')}</div>`;
}
function productDetails(i){if(i.pill)return pillDescription(Object.keys(ITEMS).find(k=>ITEMS[k]===i));if(i.skill){const k=SKILLS[i.skill];return REALMS[i.realm??0]+'可购 · 研读学习'+k.name+' · '+k.mana+'法力 · 基础伤害×'+k.power+' · 品质加成'+i.grade*15+'%';}const id=Object.keys(ITEMS).find(k=>ITEMS[k]===i),category=itemCategory(id);return elementLabel(i)+'属性 · '+({seed:'种植耗1份种子，收获对应品质仙草',herb:'可炼丹、出售或抵债，较高品质可替代同类材料',mineral:'用于升级丹炉，炼丹不消耗矿石',monster:'用于丹方中的妖兽内丹需求'}[category]??'材料')+(i.sell?' · 回收'+i.sell+'灵石':' · 不回收');}
function market(){return heading('','山间集市','每七个游戏日刷新 · '+(7-(state.day-1)%7)+'日后换货 · 商品较商店便宜')+'<div class="callout"><p>摊主只展示货物名称与价格，详细属性需购入后在背包或人物中查看。偶有传说级货物，每摊限购一份。</p></div><div class="cards two">'+state.marketOffers.map(o=>{const i=({item:ITEMS,weapon:WEAPONS,equipment:EQUIPMENT})[o.kind][o.item];return '<article class="card"><span class="medallion small">摊</span><h3>'+i.name+'</h3><p>'+o.price+'灵石</p>'+button(o.sold?'已售罄':'购入','market-buy','data-id="'+o.id+'"',o.sold)+'</article>';}).join('')+'</div>';}
function shop(){
  const filters={materials:'种子材料',pills:'丹药',weapons:'武器',equipment:'装备',books:'技能书'};
  let content='';
  if(shopTab==='materials'||shopTab==='pills')content=`<div class="cards two">${Object.entries(ITEMS).filter(([k,i])=>i.price&&k!=='dew'&&!i.legacyVariant&&i.grade<5&&i.grade===shopGrade&&(shopTab==='pills'?i.pill:!i.pill&&!i.skill)).map(([k,i])=>`<article class="card shop-card"><div class="card-top">${itemTag(k)}${gradeBadge(k)}</div><h3>${i.name}</h3><p>库存 ${state.inventory[k]}${i.realm?' · '+REALMS[i.realm]+'解锁':''}<br>${productDetails(i)}</p><div class="card-bottom"><strong>${number(i.price)} <small>灵石</small></strong>${button('购买','buy',`data-item="${k}"`,state.realm<(i.realm??0))}</div>${k==='seed'?button('购买5份','buy','data-item="seed" data-qty="5"',false,'subtle'):''}</article>`).join('')}</div>`;
  if(shopTab==='weapons')content=`<div class="cards two">${Object.entries(WEAPONS).filter(([,w])=>w.price&&w.grade<5&&w.grade===shopGrade).map(([k,w])=>`<article class="card">${pixelIcon('sword')}<h3>${PILL_GRADES[w.grade]} · ${w.name}</h3><p>${elementLabel(w)}属性 · 攻击 ${w.attack} · ${REALMS[w.realm]}可用</p><div class="card-bottom"><strong>${number(w.price)}灵石</strong>${button(state.weapons.includes(k)?'已拥有':'购买','buy-weapon',`data-item="${k}"`,state.weapons.includes(k)||state.realm<w.realm)}</div></article>`).join('')}</div>`;
  if(shopTab==='equipment')content=`<div class="cards two">${Object.entries(EQUIPMENT).filter(([,e])=>e.grade<5&&e.grade===shopGrade).map(([k,e])=>`<article class="card"><span class="badge">${EQUIPMENT_SLOTS[e.slot]}</span><h3>${PILL_GRADES[e.grade]} · ${e.name}</h3><p>${elementLabel(e)}属性 · ${equipmentText(e)}<br>${REALMS[e.realm]}可用</p><div class="card-bottom"><strong>${number(e.price)}灵石</strong>${button(state.ownedEquipment.includes(k)?'已拥有':'购买','buy-equipment',`data-item="${k}"`,state.ownedEquipment.includes(k)||state.realm<e.realm)}</div></article>`).join('')}</div>`;
  if(shopTab==='books')content='<div class="cards two">'+Object.entries(ITEMS).filter(([,i])=>i.skill&&i.grade<5&&i.grade===shopGrade).map(([id,i])=>'<article class="card">'+itemIcon(id)+'<h3>'+i.name+'</h3><p>'+elementLabel(i)+' · '+PILL_GRADES[i.grade]+' · 库存 '+state.inventory[id]+'</p><p>'+productDetails(i)+'</p>'+button('购买 · '+i.price+'灵石','buy','data-item="'+id+'"',state.realm<(i.realm??0))+'</article>').join('')+'</div>';
  return heading('','清溪小市','商店展示详细信息，不出售传说级物品。武器装备购买后主动穿戴。')+`<div class="panel-tabs">${Object.entries(filters).map(([key,label])=>`<button class="tab-btn ${shopTab===key?'active':''}" data-action="shop-tab" data-filter="${key}">${label}</button>`).join('')}</div>`+`<div class="panel-tabs">${PILL_GRADES.slice(0,5).map((g,i)=>button(g,'shop-grade',`data-grade="${i}"`,shopGrade===i)).join('')}</div>`+content+`<div class="quest-note"><span>库</span><p>出售材料或服用丹药，请前往背包。</p>${button('打开背包','navigate','data-page="warehouse"',false,'subtle')}</div>`;
}
function orders(){
 const cards=state.orders.map(o=>{const inactive=o.done||o.ignored;return '<article class="order-tile '+(inactive?'order-inactive':'')+'"><div class="order-npc"><span class="order-npc-avatar">'+pixelIcon('hero')+'</span><strong>'+o.owner+'</strong></div><div class="order-content"><small>'+(o.done?'已完成':o.ignored?'已忽略':'所需物品')+'</small><div class="order-item-icon">'+itemIcon(o.item)+'</div><h3>'+ITEMS[o.item].name+'</h3><b>× '+o.qty+'</b><p>持有 '+state.inventory[o.item]+' / '+o.qty+'</p><strong class="order-pay">'+number(o.reward)+'<small> 灵石</small></strong><small>信誉 +5</small></div><div class="order-tile-actions">'+button(o.done?'完成':o.ignored?'忽略':'完成','order','data-id="'+o.id+'"',inactive||state.inventory[o.item]<o.qty)+button('忽略','ignore-order','data-id="'+o.id+'"',inactive,'subtle')+'</div></article>';}).join('');
 return '<div class="order-board"><div class="order-board-top"><h2>道友订单</h2><span>'+ (7-(state.day-1)%7)+'日后刷新</span></div><div class="order-board-grid">'+cards+Array.from({length:Math.max(0,6-state.orders.length)},()=>'<div class="order-tile order-placeholder"><span>暂无委托</span></div>').join('')+'</div><p class="order-board-note">道友信誉 '+state.reputation+' · 忽略订单无罚金，七日后统一换新。</p></div>';
}

function growthPanel(){return '<div class="growth-road">'+growthMilestones(state).map(([name,done,text])=>'<p><strong>'+(done?'已解锁 · ':'下一步 · ')+name+'</strong><br>'+text+'</p>').join('')+'<p>炼丹等级提高成功率；丹炉开放品级；住宅开放储物和药田容量。</p></div>';}
function cultivate(){
 const capped=state.realm>=REALMS.length-1&&state.level>=10,gain=28*(state.aptitude===2?2:1),needsFoundationPill=state.realm===0&&state.level>=10,hasFoundationPill=state.inventory.foundationPill>0;
 const breakthroughHint=needsFoundationPill?`炼气突破筑基需筑基丹 ×1 · 背包 ${hasFoundationPill?'已备妥':'暂无'}${state.cultivation<80?' · 还需修满80修为':''}`:'累计80修为可突破；突破消耗80修为，不推进日期。';
 const breakthroughButton=needsFoundationPill&&!hasFoundationPill?button('前往商店购买筑基丹','foundation-shop'):'';
 return heading('','修炼 · 大道漫漫','在住宅内的蒲团修炼，修为积满后手动突破；突破大境界需对应丹药。')+`<div class="cultivation-card"><div class="realm-orb"><span>${REALMS[state.realm]}</span><strong>${state.level}</strong><small>级</small></div><div><span class="eyebrow">当前修为</span><h3>${state.cultivation} <small>/ 80</small></h3><div class="meter"><i style="width:${Math.min(100,state.cultivation/80*100)}%"></i></div><p>资质${state.aptitude===2?'卓越':'低劣'} · 修炼一日 +${gain} 修为</p><p>${breakthroughHint}</p>${resourceMeter('丹毒',state.toxin,100,'toxin')}<div class="actions">${button(capped?'当前版本上限':'修炼一日','cultivate','',capped)}${button(capped?'已达当前版本上限':state.level===10?'突破大境界':'突破一级','breakthrough','',state.cultivation<80||capped||needsFoundationPill&&!hasFoundationPill,'gold')}${breakthroughButton}</div></div></div><div class="stat-grid"><div><small>剩余寿元</small><strong>${lifeLeft(state).toFixed(1)}年</strong></div><div><small>神识</small><strong>${10+state.realm*15+state.level}</strong></div><div><small>种植熟练度</small><strong>${state.farming}</strong></div><div><small>炼丹等级</small><strong>${alchemyLevel(state)}级 · ${alchemyProgress(state)}</strong></div></div>${growthPanel()}${button('前往背包服丹','navigate','data-page="warehouse"',false,'subtle')}`;
}
function characterGrowth(){
 const capped=state.realm>=REALMS.length-1&&state.level>=10;
 const next=state.level<10?REALMS[state.realm]+(state.level+1)+'级':capped?'当前版本上限':REALMS[state.realm+1]+'一级';
 const needsFoundationPill=state.realm===0&&state.level>=10,hasFoundationPill=state.inventory.foundationPill>0;
 const hint=capped?'已达到当前版本最高境界金丹十级。':needsFoundationPill?`炼气突破筑基需筑基丹×1（背包${hasFoundationPill?'已备':'未备'}），修为需达到80。`:state.cultivation>=80?'修为已满80，打开住宅管理即可突破。':'住宅中修炼或服用修为丹，积满80修为后即可突破。';
 return `<div class="feature-strip character-growth"><div><span class="eyebrow">人物成长 · 下一步 ${next}</span><h3>${REALMS[state.realm]}${state.level}级 · 修为 ${state.cultivation}/80</h3><div class="meter"><i style="width:${Math.min(100,state.cultivation/80*100)}%"></i></div><p>${hint}</p></div>${button(state.cultivation>=80&&!capped?'前往住宅突破':'前往住宅修炼','home-panel','',capped,'subtle')}</div>`;
}
function person(){
 const slotButton=slot=>{const id=equippedId(state,slot);return `<button class="equipment-slot" data-action="equipment-slot" data-slot="${slot}" aria-label="${EQUIPMENT_SLOTS[slot]} · ${EQUIPMENT[id]?.name??'未装备'}"><small>${EQUIPMENT_SLOTS[slot]}</small><strong>${EQUIPMENT[id]?.name??'未装备'}</strong></button>`;};
 return heading('','人物 · 无名散修',REALMS[state.realm]+state.level+'级 · '+(state.aptitude===2?'卓越':'低劣')+'资质')+`${characterGrowth()}<div class="equipment-layout"><div>${['head','body','legs','feet'].map(slotButton).join('')}</div><img src="${artUrl('hero.png')}" class="person-sprite" alt="散修人物"><div>${['back','charm','neck','ring'].map(slotButton).join('')}</div></div><div class="stat-grid"><div><small>五行灵根</small><strong>金木水火土</strong></div><div><small>法力</small><strong>${Math.ceil(state.mana)}/${maxMana(state)}</strong></div><div><small>攻击</small><strong>${attack(state)}</strong></div><div><small>防御</small><strong>${defense(state)}</strong></div><div><small>剩余寿元</small><strong>${lifeLeft(state).toFixed(1)}年</strong></div><div><small>道友信誉</small><strong>${state.reputation}</strong></div></div><div class="section-line"><h3>武器 · ${WEAPONS[state.weapon].name}</h3></div><div class="cards two">${state.weapons.map(k=>`<article class="card compact">${pixelIcon('sword')}<h3>${WEAPONS[k].name}</h3><p>${elementLabel(WEAPONS[k])}属性 · 武器攻击 ${WEAPONS[k].attack}</p>${button(state.weapon===k?'已装备':'装备','weapon',`data-item="${k}"`,state.weapon===k)}</article>`).join('')}</div><div class="quest-note"><span>衣</span><p>点击部位更换装备。穿戴提升属性，不直接恢复气血。战斗优先使用库存中最高品质的回春丹。</p></div>`;
}
function bagEntries(){return [...Object.entries(ITEMS).filter(([id])=>state.inventory[id]>0).map(([id,item])=>({id,item,kind:'item',category:itemCategory(id),qty:state.inventory[id]})),...state.weapons.map(id=>({id,item:WEAPONS[id],kind:'weapon',category:'gear',qty:1})),...state.ownedEquipment.map(id=>({id,item:EQUIPMENT[id],kind:'equipment',category:'gear',qty:1}))];}
function bagIcon(entry){return entry.kind==='item'?itemIcon(entry.id):pixelIcon(entry.kind==='weapon'?'sword':({head:'hero',body:'hero',legs:'hero',feet:'hero',back:'scroll',charm:'coin',neck:'coin',ring:'coin'}[entry.item.slot]??'hero'));}
function warehouse(){
 const entries=bagEntries().filter(e=>warehouseTab==='all'||e.category===warehouseTab),labels={all:'全部',seed:'种子',herb:'仙草',mineral:'矿石',monster:'内丹',pill:'丹药',gear:'装备',book:'技能书'};
 const cells=entries.map(e=>{const equipped=e.kind==='weapon'?state.weapon===e.id:e.kind==='equipment'?equippedId(state,e.item.slot)===e.id:false;return '<button class="bag-cell quality-'+(e.item.grade??0)+'" data-action="bag-item" data-item="'+e.id+'" data-kind="'+e.kind+'" aria-label="'+e.item.name+'，数量'+e.qty+'">'+bagIcon(e)+'<span class="bag-quality"></span><b class="bag-quantity">'+e.qty+'</b>'+(equipped?'<span class="bag-equipped">装</span>':'')+'</button>';}).join('');
 return '<div class="backpack"><header class="bag-banner"><div class="bag-wallet">'+pixelIcon('coin')+' '+number(state.cash)+' <small>灵石</small></div><h2><span>背</span>包</h2><p>容量 '+inventoryCount(state)+' / '+capacity(state)+' · 装备独立存放</p><img src="'+artUrl('backpack.png')+'" alt="行囊"></header><div class="bag-scroll"><div class="bag-grid">'+cells+Array.from({length:Math.max(0,30-entries.length)},()=>'<span class="bag-cell bag-empty" aria-hidden="true"></span>').join('')+'</div>'+(entries.length?'':'<p class="bag-empty-note">这一类暂无物品</p>')+'</div><footer class="bag-footer"><button class="bag-back" data-action="navigate" data-page="person" aria-label="返回人物">←</button><div class="bag-filters" role="tablist" aria-label="背包分类">'+Object.entries(labels).map(([key,label])=>'<button role="tab" aria-selected="'+(warehouseTab===key)+'" class="'+(warehouseTab===key?'active':'')+'" data-action="warehouse-tab" data-filter="'+key+'">'+label+'</button>').join('')+'</div></footer></div>';
}
function bagDetail(){
 const e=bagEntries().find(e=>e.id===bagSelected?.id&&e.kind===bagSelected?.kind);if(!e)return '<p>物品已用完。</p>';
 const i=e.item,grade=i.grade??0;let actions='',detail='';
 if(e.kind==='item'){detail=i.pill?pillDescription(e.id):productDetails(i);if(i.pill&&!i.breakthroughOnly)actions+=button('服用','consume','data-item="'+e.id+'"',state.toxin>=100||!!i.manaRestore&&state.mana>=maxMana(state)||!!i.heal&&state.hp>=maxHP(state)||e.id==='supreme'&&state.aptitude>=2);if(i.skill)actions+=button('研读','use-skillbook','data-item="'+e.id+'"');if(i.sell)actions+=button('出售1份 · '+i.sell+'灵石','sell','data-item="'+e.id+'"',false,'subtle');}
 else if(e.kind==='weapon'){detail='攻击 '+i.attack+' · '+REALMS[i.realm]+'可用';actions=button(state.weapon===e.id?'已装备':'装备','weapon','data-item="'+e.id+'"',state.weapon===e.id||state.realm<i.realm);}
 else{detail=EQUIPMENT_SLOTS[i.slot]+' · '+equipmentText(i)+' · '+REALMS[i.realm]+'可用';actions=button(equippedId(state,i.slot)===e.id?'已穿戴':'穿戴','equip','data-item="'+e.id+'"',equippedId(state,i.slot)===e.id||state.realm<i.realm);}
 return '<div class="bag-detail"><div class="bag-detail-icon quality-'+grade+'">'+bagIcon(e)+'</div><h3>'+i.name+'</h3><p>'+PILL_GRADES[grade]+' · '+elementLabel(i)+'属性 · 数量 '+e.qty+'</p><p>'+detail+'</p><div class="actions">'+actions+'</div></div>';
}

function openEquipment(slot){
 document.querySelector('.modal')?.remove();const entries=state.ownedEquipment.filter(k=>EQUIPMENT[k].slot===slot),current=equippedId(state,slot);
 const el=document.createElement('div');el.className='modal';el.innerHTML=`<div class="modal-panel crop-dialog" role="dialog" aria-modal="true" aria-label="${EQUIPMENT_SLOTS[slot]}装备"><div class="modal-top"><h2>${EQUIPMENT_SLOTS[slot]}</h2><button class="dialog-close" data-modal="close" aria-label="关闭装备面板">×</button></div>${entries.length?entries.map(k=>`<div class="seed-option"><div><strong>${EQUIPMENT[k].name}</strong><small>${equipmentText(EQUIPMENT[k])}</small></div>${button(current===k?'已穿戴':'穿戴','equip',`data-item="${k}"`,current===k)}</div>`).join(''):'<p>尚未拥有这一部位的装备。</p>'}<div class="actions">${button('卸下','unequip',`data-slot="${slot}"`,!current,'subtle')}${button('前往商店','navigate','data-page="shop"',false,'subtle')}</div></div>`;document.body.append(el);el.querySelector('button').focus();
}
function interiorScene(){return '<div class="interior-world"><img class="room-backdrop" src="'+artUrl('interior.png')+'" alt="住宅室内：木地板、纸窗与修炼蒲团"><img class="indoor-hero" src="'+artUrl('hero.png')+'" alt="室内的散修"><button class="room-hotspot room-meditate" data-action="cultivate" aria-label="在室内修炼一日"><span>蒲团 · 修炼</span></button><button class="room-hotspot room-exit" data-action="navigate" data-page="homestead" aria-label="走出住宅"><span>出门</span></button>'+ (state.furniture.bed?'<button class="room-furniture room-bed" data-action="rest" aria-label="竹榻休养一日">'+objectIcon(7)+'<span>竹榻 · 休养</span></button>':'')+(state.furniture.cabinet?'<button class="room-furniture room-cabinet" data-action="navigate" data-page="warehouse" aria-label="打开室内储物柜">'+objectIcon(3)+'<span>储物柜</span></button>':'')+'<button class="room-label" data-action="home-panel">住宅管理</button></div>';}
function residence() {
  return heading('A PLACE TO CALL HOME','草庐虽小，亦可安身','屋舍与家具，让山间生活渐渐丰盈。')+`<div class="scene-wrap">${interiorScene()}</div><div class="feature-strip"><div class="medallion">舍</div><div><h3>${names[state.house]} · ${elementLabel(Object.values(WORLD_ITEMS)[state.house+2])}</h3><p>储物 ${inventoryCount(state)} / ${capacity(state)} · 药田上限 ${plotLimit(state)}块</p></div>${button(state.house>=3?'已完全升级':`翻修 · ${number([800,2200,6000][state.house])}灵石`,'house','',state.house>=3)}</div><div class="feature-strip"><div><h3>药田扩建</h3><p>现有 ${state.plots.length} 块 / 可容纳 ${plotLimit(state)} 块 · 新增土地为普通土地</p></div>${button('管理扩建','expand-menu')}</div><div class="cards three">${[['cabinet','储物柜',350,'储物容量 +40'],['bed','竹榻',450,'休息精力恢复 +20'],['table','炼丹工作台',650,'单次炼丹精力消耗降至12']].map(([k,n,p,d])=>{const stored=state.homeWarehouse.furniture.includes(k);return `<article class="card"><span class="medallion small">${n[0]}</span><h3>${n} · ${elementLabel(WORLD_ITEMS[k])}</h3><p>${d}</p>${state.furniture[k]?button('已安置','furniture',`data-item="${k}"`,true):stored?button('已收纳 · 去仓库安置','home-warehouse','data-filter="furniture"',false,'subtle'):button(`${p}灵石 · 购置`,'furniture',`data-item="${k}"`,false)}${state.furniture[k]?button('收纳至家园仓库','store-furniture',`data-item="${k}"`,false,'subtle'):''}</article>`;}).join('')}</div>`;
}
function debt() {
  return turnoverPanel()+economyPanel()+ heading('THE PRICE OF AMBITION','旧债未了，前路仍长','有现金时仅扣现金；到访时零现金才扣灵药仙草。')+`<div class="debt-summary"><span class="eyebrow">未偿贷款</span><h2>${number(state.debt)} <small>灵石</small></h2><p>${state.debt?`下一次催债：第${state.nextCollection}日 · 先按剩余欠款增加1%利息`:'债契已清，当前不计息、不催债。'}</p></div><div class="stat-grid"><div><small>境界基础额度</small><strong>${number([1000000,2000000,5000000][state.realm])}</strong></div><div><small>寿元系数</small><strong>${lifeFactor(state).toFixed(3)}</strong></div><div><small>最终额度</small><strong>${number(credit(state))}</strong></div><div><small>可借金额</small><strong>${number(availableCredit(state))}</strong></div></div><article class="card money-form"><label for="amount">借款 / 还款金额（整数灵石）</label><input id="amount" type="number" min="1" step="1" value="100" inputmode="numeric"><div class="actions">${button('主动还款','repay')}${button('借入灵石','borrow','',!availableCredit(state),'subtle')}</div></article><div class="callout danger"><span>!</span><div><strong>催收后仍欠款，且现金与灵药仙草均为零，本局结束。</strong><p>装备、丹药、住宅不抵债，也不豁免失败。寿元变化会调整可借额度，额度不足不会立即催债。</p></div></div>`;
}
function realm() {
  const d=dungeonById(selectedDungeon)??DUNGEONS[0],unlocked=dungeonUnlocked(state,d),cleared=state.clearedDungeons.includes(d.id),canSweep=sweepAvailable(state,d.id),wait=sweepWait(state,d.id);
  return heading('','御剑 · 十方秘境','随着境界与等级提升，逐一打开山外的道路。')+`<div class="dungeon-detail" style="--dungeon-accent:${d.accent};--dungeon-bg:${d.sky}"><span class="eyebrow">第 ${String(DUNGEONS.indexOf(d)+1).padStart(2,'0')} 境 · ${dungeonLabel(d)}</span><div class="detail-top"><div>${pixelIcon('portal')}<h2>${d.name}</h2><p>${d.desc}</p></div><div class="dungeon-actions">${button(unlocked?'御剑出发':'尚未解锁','enter',`data-dungeon="${d.id}"`,!unlocked,'gold')}${button(!cleared?'通关后扫荡':canSweep?'一键扫荡 · 1次':wait+'日后恢复','sweep',`data-dungeon="${d.id}"`,!canSweep,'subtle')}</div></div><div class="dungeon-meta"><span>镇境妖兽：${d.boss}</span><span>${state.clearedDungeons.includes(d.id)?'已击败镇境妖兽':'尚未通关'}</span><span>${state.doubleJump?'已领悟二段跳':'古碑可领悟二段跳'}</span></div></div><p class="sweep-note">进入秘境与一键扫荡均消耗30点精力；每境扫荡限1次，使用后7个游戏日恢复，不累积。扫荡直接领取基础资源。</p>${cleared?`<div class="sweep-loot">${Object.entries(sweepLoot(d)).map(([k,q])=>`<span>${ITEMS[k].name} × ${q}</span>`).join('')}</div>`:''}<div class="dungeon-map">${DUNGEONS.map((entry,i)=>`<button class="dungeon-node ${entry.id===d.id?'selected':''} ${dungeonUnlocked(state,entry)?'unlocked':'locked'}" data-action="select-dungeon" data-dungeon="${entry.id}" style="--node-color:${entry.accent}"><span class="node-index">${String(i+1).padStart(2,'0')}</span>${pixelIcon(dungeonUnlocked(state,entry)?'portal':'scroll')}<strong>${entry.name}</strong><small>${dungeonLabel(entry)}</small><span class="node-status">${state.clearedDungeons.includes(entry.id)?'已通关':dungeonUnlocked(state,entry)?'可探索':'未解锁'}</span></button>`).join('')}</div><div class="quest-note"><span class="quest-marker">剑</span><div><strong>出行准备 · 回春丹 ${Object.entries(ITEMS).filter(([,i])=>i.heal).reduce((n,[id])=>n+state.inventory[id],0)} · 回灵丹 ${Object.entries(ITEMS).filter(([,i])=>i.manaRestore).reduce((n,[id])=>n+state.inventory[id],0)} · 丹毒 ${state.toxin}/100</strong><p>往返共两日。战败保留一半本次收获；丹毒与经营共用。携带技能 ${state.skillLoadout.length}/4，当前法力 ${Math.ceil(state.mana)}。${d.id==='qinglan'?'高处药谷有月华种子，需御风步回访；首次通关发现凝露丹方。':'探索获得高阶材料。'}</p></div></div>`;
}
function skillsPanel(){
 const learned=Object.entries(SKILLS).filter(([id])=>state.learnedSkills.includes(id));
 const groups=Object.entries(ELEMENTS).map(([element,label])=>{
  const skills=learned.filter(([,k])=>k.element===element);if(!skills.length)return '';
  return '<section class="skill-element-group" aria-label="'+label+'属性技能"><h3>'+label+'属性</h3><div class="cards two">'+skills.map(([id,k])=>{const equipped=state.skillLoadout.includes(id),grade=state.skillGrades[id]??0;return '<article class="card"><h3>'+k.name+'</h3><p>'+PILL_GRADES[grade]+' · 消耗 '+k.mana+'法力 · 伤害×'+(k.power*(1+.15*grade)).toFixed(2)+'</p>'+button(equipped?'卸下':'携带','toggle-skill','data-item="'+id+'"',!equipped&&state.skillLoadout.length>=4)+'</article>';}).join('')+'</div></section>';
 }).join('');
 return '<h3>已学技能</h3><p>秘境携带 '+state.skillLoadout.length+'/4 · 五灵根</p>'+ (groups||'<p>尚未学习技能，可购买技能书后在背包研读。</p>');
}

const originalPerson=person;const personWithSkills=()=>'<div class="panel-tabs">'+button('装备与技能','navigate','data-page="person"')+button('背包','navigate','data-page="warehouse"')+button('债务','navigate','data-page="debt"')+'</div>'+originalPerson()+skillsPanel();
function home(){return interiorScene();}
function storyPanel(id){const story=STORIES[id];return '<div class="story-dialog"><small>'+story.speaker+'</small><h3>'+story.title+'</h3><p>'+story.text+'</p>'+button('前往查看','story-go','data-id="'+id+'" data-page="'+story.page+'"')+button('收起','read-story','data-id="'+id+'"',false,'subtle')+'</div>';}
function chapterPanel(){const completed=QUESTS.filter(q=>state.tutorial.completed.includes(q.id)).length;const next=QUESTS.find(q=>!state.tutorial.completed.includes(q.id));return '<section class="chapter-road"><h3>'+(state.journey.chapterComplete?'第一章完成 · 草庐立足':'第一章 · 草庐立足')+'</h3><div class="meter"><i style="width:'+completed/QUESTS.length*100+'%"></i></div><p>'+completed+' / '+QUESTS.length+' 个成长目标'+(next?' · 当前：'+next.title:' · 接下来经营月华灵田，向洗髓丹迈进')+'</p>'+(next?button('前往当前目标','navigate','data-page="'+next.page+'"'):'')+'<details class="chapter-notes"><summary>来信与洗髓线索</summary><h3>山居来信</h3>'+state.journey.available.map(id=>button((state.journey.seen.includes(id)?'':'新 · ')+STORIES[id].title,'story','data-id="'+id+'"',false,'subtle')).join('')+'<h3>洗髓丹线索</h3><p>'+(state.journey.dewRecipe?'青岚残卷已发现：凝露丹用于低丹毒修炼。洗髓天灵丹需月华仙草6株、妖兽内丹3枚，金丹境界与传说丹炉。':'击败青岚兽王，寻找丹方残卷。')+'</p><p>修炼与生产持续支持改命；清偿全部债务并服用洗髓天灵丹达成主线结局。</p></details></section>';}
function turnoverPanel(){const herb=materialCount(state,'herb'),seeds=seedCount(state,'seed'),growing=state.plots.filter(Boolean).length;return '<section class="turnover-panel"><h3>下一轮生产准备</h3><p>青灵草种子 '+seeds+'份 · 青灵草 '+herb+'株 · 在田作物 '+growing+'块</p><p>建议催收前保留至少2份种子与2株仙草。有现金只收现金，零现金才扣库存仙草；种子和未收获作物不能代替仙草抵债。资产耗尽仍会失败。</p>'+button('采购2份周转种子 · 60灵石','buy','data-item="seed" data-qty="2"',state.cash<60||inventoryCount(state)+2>capacity(state))+button('查看药田','navigate','data-page="farm"',false,'subtle')+button('背包卖草周转','navigate','data-page="warehouse"',false,'subtle')+'</section>';}
function questPanel(){
 const t=state.tutorial,done=QUESTS.filter(q=>t.completed.includes(q.id)),ongoing=QUESTS.filter(q=>!t.completed.includes(q.id)),list=questTab==='completed'?done:ongoing;
 return chapterPanel()+'<div class="quest-tabs" role="tablist" aria-label="任务分类"><button role="tab" aria-selected="'+(questTab==='ongoing')+'" class="'+(questTab==='ongoing'?'selected':'')+'" data-action="quest-tab" data-filter="ongoing">进行中任务 ('+ongoing.length+')</button><button role="tab" aria-selected="'+(questTab==='completed')+'" class="'+(questTab==='completed'?'selected':'')+'" data-action="quest-tab" data-filter="completed">已完成任务 ('+done.length+')</button></div><div class="quest-list">'+(list.length?list.map(q=>'<article class="quest-list-row"><h3>'+q.title+'</h3><p>'+q.text+'</p><small>奖励：'+(q.cash?q.cash+'灵石':Object.entries(q.reward??{}).map(([id,n])=>ITEMS[id].name+'×'+n).join('、')||'第一章完成')+'</small><div>'+ (questTab==='completed'?button(t.claimed.includes(q.id)?'已领取':'领取奖励','claim-quest','data-id="'+q.id+'"',t.claimed.includes(q.id)):button('前往','navigate','data-page="'+q.page+'"'))+'</div></article>').join(''):'<p class="quest-empty">'+(questTab==='completed'?'暂无已完成任务':'所有任务均已完成')+'</p>')+'</div>';
}

function economyPanel(){const e=state.economy,t=economyTotals(e.entries);const last=e.lastPeriod;return '<div class="chapter-panel"><h3>本期收支 · 第'+e.startDay+'日起</h3><p>交易收入 '+t.trade+' · 订单 '+t.order+' · 任务奖励 '+t.reward+'<br>经营支出 '+t.expense+' · 主动还款 '+t.repay+' · 催收 '+t.collection+'<br>经营净收入（含奖励） '+t.net+' · 不含奖励 '+t.operating+'<br>下期预计利息 '+Math.ceil(state.debt*.01)+'灵石</p>'+(last?'<p>上一期经营净收入 '+economyTotals(last.entries).net+' · 催收还款 '+last.repaid+' · 利息 '+last.interest+'</p>':'')+'</div>';}
function isoIcon(i){return '<span class="iso-tool-icon" style="background-position:'+(i%2?100:0)+'% '+(i>=2?100:0)+'%"></span>';}
function editTools(){return homeEdit?'<div class="iso-edit-toolbar">'+button(isoIcon(0)+'移动物件','iso-tool','data-tool="move"',false,homeEdit.tool==='move'?'active':'')+button(isoIcon(1)+'铺／拆路','iso-tool','data-tool="road"',false,homeEdit.tool==='road'?'active':'')+button('回收','iso-tool','data-tool="recycle"',false,homeEdit.tool==='recycle'?'active':'')+button(isoIcon(2)+'保存','iso-save')+button(isoIcon(3)+'取消','iso-cancel')+'</div><div class="iso-edit-hint">'+(homeEdit.tool==='recycle'?'点击药田或装饰回收；住宅与炼丹房会提示不可回收':homeEdit.tool==='road'?'点击空地铺路，点击道路拆除':homeEdit.selected?'已选 '+objectName(homeEdit.layout.objects.find(o=>o.id===homeEdit.selected),state)+' · 点击空地放置':'点击地图上任意对象后移动或回收')+'</div>':'<button class="iso-edit-button" data-action="iso-edit">'+isoIcon(0)+'布置</button>';}
function homestead(){syncLayout(state);return isoMarkup(state,homeEdit?.layout??state.homeLayout,homeEdit)+editTools()+(homeEdit?'<div class="iso-storage"><strong>家园仓库 · 已回收摆件</strong>'+homeEdit.layout.objects.filter(o=>o.stored).map(o=>button('选中放置 '+objectName(o,state),'iso-restore','data-object="'+o.id+'"')).join('')+'</div>':'<button class="iso-warehouse-button" data-action="home-warehouse">'+objectIcon(3)+'<span>家园仓库</span></button>');}
function beginHomeEdit(id=null){syncLayout(state);homeEdit??={layout:structuredClone(state.homeLayout),selected:id,tool:'move'};if(id)homeEdit.selected=id;render();}
function homeWarehousePanel(){
 const furniture=[['cabinet','储物柜','储物容量 +40'],['bed','竹榻','休息精力恢复 +20'],['table','炼丹工作台','炼丹精力消耗降至12']];
 const furnishing=furniture.filter(([id])=>state.furniture[id]||state.homeWarehouse.furniture.includes(id)).map(([id,name,effect])=>'<article class="home-storage-row"><span class="home-storage-glyph">'+name[0]+'</span><div class="home-storage-name"><strong>'+name+'</strong><small>'+effect+' · '+(state.furniture[id]?'已安置':'仓库中')+'</small></div><div class="actions">'+(state.furniture[id]?button('收纳','store-furniture','data-item="'+id+'"'):button('重新安置','place-furniture','data-item="'+id+'"'))+'</div></article>').join('');
 const stowed=(state.homeLayout?.objects??[]).filter(o=>o.stored).map(o=>'<article class="home-storage-row"><span class="home-storage-glyph">田</span><div class="home-storage-name"><strong>'+objectName(o,state)+'</strong><small>已回收 · 放回地图时保留原有生长状态</small></div><div class="actions">'+button('重新摆放','home-place-object','data-object="'+o.id+'"')+'</div></article>').join('');
 return '<p class="home-warehouse-note">家园仓库用于收纳家具与摆件。家具收纳后增益暂停，重新安置即恢复；回收的药田与摆件也可在此重新摆放。药材、矿石、内丹和丹药请存放在背包中。</p><div class="home-storage-list">'+(furnishing+stowed||'<p>暂无收纳家具或摆件，可以在住宅管理中收纳家具，或在布置模式中回收摆件。</p>')+'</div>';
}function editHomeTile(tile,id){if(!homeEdit)return;if(homeEdit.tool==='recycle'){const o=homeEdit.layout.objects.find(o=>o.id===id);if(!o){toast('点击要回收的药田或装饰');return;}if(['house','alchemy'].includes(o.kind)){toast('住宅和炼丹房不可回收');return;}o.stored=true;homeEdit.selected=null;render();toast('已回收，可从收纳栏重新放置');return;}if(homeEdit.tool==='move'){if(id){homeEdit.selected=id;render();return;}if(!homeEdit.selected){toast('先选中住宅、炼丹洞、药田或柳树');return;}const problem=placementProblem(state,homeEdit.layout,homeEdit.selected,tile.x,tile.y);if(problem){toast(problem);return;}const o=homeEdit.layout.objects.find(o=>o.id===homeEdit.selected);o.x=tile.x;o.y=tile.y;o.stored=false;homeEdit.layout.roads=homeEdit.layout.roads.filter(p=>!footprint(o).some(q=>q.x===p.x&&q.y===p.y));homeEdit.selected=null;render();return;}
 if(!unlocked(state,tile.x,tile.y)){toast('这里尚未开放，请先升级住宅');return;}if(homeEdit.layout.objects.some(o=>footprint(o).some(p=>p.x===tile.x&&p.y===tile.y))){toast('道路不能铺在建筑或药田下');return;}const i=homeEdit.layout.roads.findIndex(p=>p.x===tile.x&&p.y===tile.y);if(i>=0)homeEdit.layout.roads.splice(i,1);else homeEdit.layout.roads.push(tile);render();}
function walkHome(tile){const path=walkingPath(state,state.homeLayout,hero,tile);if(!path.length)return;cancelAnimationFrame(walkFrame);let previous=performance.now(),destination=path.shift();const step=now=>{const dt=Math.min(.05,(now-previous)/1000);previous=now;const dx=destination.x-hero.x,dy=destination.y-hero.y,length=Math.hypot(dx,dy),speed=dt*3;if(length<=speed){hero={...destination};destination=path.shift();}else{hero.x+=dx/length*speed;hero.y+=dy/length*speed;}const canvas=document.querySelector('.iso-canvas');if(!canvas)return;drawIsoHome(canvas,state,state.homeLayout,null,hero);if(destination)walkFrame=requestAnimationFrame(step);};walkFrame=requestAnimationFrame(step);}

function travel(){return '<div class="travel-map"><img src="'+artUrl('travel-map-bazaar.png')+'" alt="山间地图：商店、集市、秘境与订单"><button class="map-place" style="left:2%;top:49%;width:35%;height:16%" data-action="navigate" data-page="shop"><span>清溪商店</span></button><button class="map-place" style="left:36%;top:8%;width:30%;height:17%" data-action="navigate" data-page="realm"><span>十方秘境</span></button><button class="map-place" style="left:70%;top:54%;width:27%;height:17%" data-action="navigate" data-page="orders"><span>道友订单</span></button><button class="map-place bazaar-place" style="left:32%;top:66%;width:38%;height:17%" data-action="navigate" data-page="market"><span>山间集市</span></button></div>';}
function farm(){return homestead()+(homeEdit?'':'<button class="visual-action" data-action="farm-panel">药田管理</button>');}
const views={market,travel,homestead,farm,alchemy,shop,orders,cultivate,home,debt,realm,person:personWithSkills,warehouse};
function nextCollectionText(){return state.nextCollection===null?'债务已清':state.nextCollection-state.day+'日后催债';}
function visualHUD(next){const ready=state.tutorial.completed.some(id=>!state.tutorial.claimed.includes(id));return '<div class="visual-hud"><span>第'+state.day+'日 · '+number(state.cash)+'灵石</span><button data-action="menu" aria-label="游戏菜单">☰</button><div class="visual-resource-bars">'+cultivationMeter()+resourceMeter('精力',state.energy,100,'energy')+resourceMeter('丹毒',state.toxin,100,'toxin')+'</div></div><button class="visual-debt" data-action="notice-panel">'+(state.notices.length?'催债提醒':next)+'</button><button class="visual-task task-icon" data-action="chapter-panel" aria-label="任务列表"><span aria-hidden="true">!</span>'+(ready?'<i class="task-reward-dot" aria-hidden="true"></i>':'')+'</button>'+(pendingStory(state)?'<button class="visual-letter" data-action="story" data-id="'+pendingStory(state)+'" aria-label="阅读山居来信">信<i></i></button>':'');}

function homeControls(){const html=residence();return html.slice(html.indexOf('<div class="feature-strip">'))+'<h3>修炼</h3>'+cultivate()+(state.journey.dewRecipe?chapterPanel():'');}
function refreshSceneSheet(){const sheet=document.querySelector('.scene-sheet');if(!sheet)return;const title=sheet.getAttribute('aria-label');if(title==='物品详情')openSheet(title,bagDetail());if(title==='住宅')openSheet(title,homeControls());if(title==='家园仓库')openSheet(title,homeWarehousePanel());if(title==='任务')openSheet(title,questPanel());if(title==='山居来信')return; if(title==='药田')openSheet(title,farmPanel().replace(scene(true),''));if(title==='催债提醒')openSheet(title,state.notices.map(n=>'<p>'+n.text+'</p>'+button('知道了','dismiss-notice','data-day="'+n.day+'"')).join('')||'<p>'+nextCollectionText()+'</p>');}
function openSheet(title,body){document.querySelector('.modal')?.remove();const el=document.createElement('div');el.className='modal';el.innerHTML='<div class="modal-panel scene-sheet" role="dialog" aria-modal="true" aria-label="'+title+'"><div class="modal-top"><h3>'+title+'</h3><button class="dialog-close" data-modal="close" aria-label="关闭">×</button></div>'+body+'</div>';document.body.append(el);}
function render() {
  if(battle)return;
  disposeHomeCamera?.();disposeHomeCamera=null;cancelAnimationFrame(walkFrame);
  const visual=['travel','homestead','home','farm'].includes(page);
  const next=state.nextCollection===null?'债务已清':`${Math.max(0,state.nextCollection-state.day)}日后催债`;
  const navIcons={travel:'portal',homestead:'house',farm:'herb',alchemy:'furnace',shop:'shop',orders:'scroll',cultivate:'sword',home:'house',debt:'coin',realm:'portal',person:'hero',warehouse:'house'};
  root.innerHTML=`<div class="portrait-notice"><strong>请竖起手机</strong><p>一炉尘梦采用竖屏游玩</p></div><div class="game-frame ${visual?'visual-frame':page==='warehouse'?'bag-frame':''}"><header class="game-header"><div class="player-head"><img class="asset-icon" src="${artUrl('hero.png')}" alt="散修头像"><div><strong>无名散修</strong><small>${REALMS[state.realm]}${state.level}级 · ${state.aptitude===2?'卓越':'低劣'}资质</small></div></div><div class="header-resources"><span>第 ${state.day} 日</span><strong>${pixelIcon('coin')}${number(state.cash)}</strong></div><button class="menu-toggle" data-action="menu" aria-label="游戏菜单">☰</button></header><div class="game-status"><div class="status-resource-bars">${cultivationMeter()}${resourceMeter('精力',state.energy,100,'energy')}${resourceMeter('丹毒',state.toxin,100,'toxin')}</div><button data-action="navigate" data-page="debt" class="debt-warning">${next}</button></div><main class="game-screen" data-scene="${page}">${(visual?[]:state.notices).map(n=>`<div class="debt-notice"><p>${n.text}</p>${button('知道了','dismiss-notice',`data-day="${n.day}"`)}</div>`).join('')}${views[page]()}${visual?visualHUD(next):''}<details class="journal"><summary>山居手记 · 储物 ${inventoryCount(state)}/${capacity(state)} <span>▾</span></summary>${state.log.slice(0,5).map(l=>`<p>· ${l}</p>`).join('')}</details></main><nav class="scene-dock" aria-label="场景切换">${tabs.map(([k,,name])=>`<button class="dock-button ${(k==='travel'&&['travel','shop','realm','orders','market'].includes(page)||k==='homestead'&&['homestead','farm','home','cultivate','alchemy'].includes(page)||k==='person'&&['person','warehouse','debt'].includes(page))?'active':''}" data-action="navigate" data-page="${k}" aria-label="${name}" aria-current="${page===k?'page':'false'}">${pixelIcon(navIcons[k])}<span>${name==='修炼与装备'?'修炼':name==='道友订单'?'订单':name}</span></button>`).join('')}</nav></div>`;
  document.querySelectorAll('.world-canvas').forEach(canvas=>drawVillage(canvas,state,page==='farm'?farmPage:0,visual?576:420));
  if(['homestead','farm'].includes(page)){syncLayout(state);const view=document.querySelector('.iso-viewport');drawIsoHome(view.querySelector('canvas'),state,homeEdit?.layout??state.homeLayout,homeEdit,hero);disposeHomeCamera=attachIsoCamera(view,homeCamera,{longPress:beginHomeEdit,isEditing:()=>!!homeEdit,editTile:editHomeTile,walk:walkHome});}

  if(state.failed)showModal('债契尽头','债主收走了最后的资产。你仍有一座老屋，却已没有偿债的灵石和仙草。本局结束。',[['重新开始','restart'],['查看债务','close']]);
  else if(state.won && !sessionStorage.getItem('chenmeng-win')){sessionStorage.setItem('chenmeng-win','1');showModal('洗髓重生，旧债已清','你从底层散修走到这里，终于可以为自己而修行。可以继续经营和探索秘境。',[['继续山居','close']]);}
}
function openPlot(index,mode='plant') {
  if(!Number.isInteger(index)||index<0||index>=state.plots.length)return;
  document.querySelector('.modal')?.remove();
  const p=state.plots[index],ready=p&&state.day>=p.ready,soilId=plotSoil(state,index),soil=SOILS[soilId];
  const crop=CROPS[p?.crop??'herb'],qty=harvestYield(state,p);
  const title=mode==='soil'?'药田'+(index+1)+' · 改造土地':p?crop.name+' · '+(ready?'已成熟':'生长中'):'药田'+(index+1)+' · 选择种子';
  const el=document.createElement('div');el.className='modal';
  let body='';
  if(mode==='soil')body=`<p>当前为${soil.name}。只能改造空田；切换土地按目标价格付费，恢复普通土地免费，不返还改造费用。</p><div class="soil-options">${Object.entries(SOILS).map(([key,t])=>`<div class="seed-option"><span class="soil-swatch" style="background:${t.color}"></span><div><strong>${t.name}</strong><small>${key==='normal'?'可种青灵草':Object.values(CROPS).filter(c=>c.soils.length===1&&c.soils.includes(key)).map(c=>c.name).join('、')} · ${t.price}灵石</small></div>${button(key===soilId?'当前土地':state.house<t.house?'住宅未解锁':'改造','soil',`data-index="${index}" data-soil="${key}"`,key===soilId||state.house<t.house||!!p||state.cash<t.price)}</div>`).join('')}</div><div class="actions"><button class="btn subtle" data-action="plot" data-index="${index}">返回种植</button><button class="btn subtle" data-modal="close">关闭</button></div>`;
  else if(p)body=`${itemIcon(crop.item)}<p>${ready?'仙草已经成熟，可以收获。':'作物正在生长；休息和修炼会推进游戏日期。'}</p><div class="crop-stats"><div><small>剩余天数</small><strong>${Math.max(0,p.ready-state.day)} 日</strong></div><div><small>预计收获</small><strong>${qty} 株</strong></div></div><div class="actions">${button(ready?'收获仙草':'尚未成熟','harvest',`data-index="${index}"`,!ready)}<button class="btn subtle" data-modal="close">返回药田</button></div><p class="farm-subtitle">收获消耗5精力 · 收获后保留${soil.name}</p>`;
  else body=`<p>${soil.name} · 当前精力 ${state.energy}。特殊仙草需要对应土地。</p><div class="seed-options">${Object.entries(CROPS).map(([key,c])=>{const block=plantingBlock(state,index,key);return `<div class="seed-option">${itemIcon(c.seed)}<div><strong>${c.name}</strong><select class="seed-quality" data-seed-for="${key}" aria-label="${c.name}种子品质">${materialKeys(state,c.seed).map(id=>`<option value="${id}">${PILL_GRADES[ITEMS[id].grade]} ×${state.inventory[id]}</option>`).join('')}</select><small>种子 ${seedCount(state,c.seed)} · ${c.days}日成熟 · ${harvestYield(state,{crop:key})}株</small><small>${c.soils.length===1?'需'+c.soils.map(k=>SOILS[k].name).join('或')+' · ':''}${block||'可以种植'}</small></div>${button('播种'+c.name,'plant',`data-index="${index}" data-crop="${key}"`,!!block)}</div>`;}).join('')}</div><div class="actions">${button('改造土地','soil-menu',`data-index="${index}"`,false,'subtle')}<button class="btn subtle" data-modal="close">返回药田</button></div><p class="farm-subtitle">播种消耗1份种子与8精力；青灵草适应所有土地。</p>`;
  el.innerHTML=`<div class="modal-panel crop-dialog" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-top"><span class="eyebrow">药田 ${index+1} / ${state.plots.length} · ${soil.name}</span><button class="dialog-close" data-modal="close" aria-label="关闭药田弹窗">×</button></div><h2>${title}</h2>${body}</div>`;
  document.body.append(el);el.querySelector('button').focus();
}
function openExpansion() {
  document.querySelector('.modal')?.remove();const limit=plotLimit(state),price=expansionPrice(state),full=state.plots.length>=limit;
  const el=document.createElement('div');el.className='modal';
  el.innerHTML=`<div class="modal-panel crop-dialog" role="dialog" aria-modal="true" aria-label="药田扩建"><div class="modal-top"><span class="eyebrow">${names[state.house]}</span><button class="dialog-close" data-modal="close" aria-label="关闭扩建弹窗">×</button></div><h2>药田扩建</h2><div class="crop-stats"><div><small>现有药田</small><strong>${state.plots.length} 块</strong></div><div><small>住宅上限</small><strong>${limit} 块</strong></div></div><p>${full?(state.house===3?'宅院药田已全部开垦。':'当前容量已满，请先升级房屋。'):'花费'+price+'灵石新增一块普通药田。升级房屋不会自动新增药田。'}</p><div class="actions">${button(full?'容量已满':'扩建 · '+price+'灵石','expand-plot','',full||state.cash<price,'gold')}${button('前往住宅','navigate','data-page="home"',false,'subtle')}</div><p class="farm-subtitle">住宅容量：4 → 6 → 8 → 12块。每次扩建需单独付费。</p></div>`;
  document.body.append(el);el.querySelector('button').focus();
}
function showModal(title,text,options=[['知道了','close']]) {
  document.querySelector('.modal')?.remove();
  const el=document.createElement('div');el.className='modal';el.innerHTML=`<div class="modal-panel ${title==='山居菜单'?'settings-panel':''}" role="dialog" aria-modal="true" aria-label="${title}"><span class="eyebrow">一炉尘梦</span><h2>${title}</h2><p>${text}</p><div class="actions">${options.map(([t,a])=>`<button class="btn" data-modal="${a}">${t}</button>`).join('')}</div></div>`;document.body.append(el);el.querySelector('button').focus();
}
function restart(){homeCamera.initialized=false;homeEdit=null;hero={x:7,y:6};battle?.dispose();battle=null;state=initialState();page='homestead';farmPage=0;shopTab='materials';warehouseTab='all';recipeGrade=0;selectedDungeon=DUNGEONS[0].id;save();sessionStorage.removeItem('chenmeng-win');document.querySelector('.modal')?.remove();render();}
function enter(dungeonId=selectedDungeon) {
  disposeHomeCamera?.();disposeHomeCamera=null;
  const dungeon=dungeonById(dungeonId)??DUNGEONS[0];
  try {state=transition(state,'expedition',{dungeonId:dungeon.id});save();if(state.failed){render();return;}}catch(e){toast(e.message);return;}
  root.innerHTML=`<div class="portrait-notice"><strong>请竖起手机</strong><p>一炉尘梦采用竖屏游玩</p></div><div class="battle-page"><header><div><span class="eyebrow">御剑 · ${dungeon.name}</span><h2>${dungeon.name} · ${ELEMENTS[dungeonElement(dungeon)]}属性妖兽</h2></div><button class="btn" id="retreat">撤离秘境 →</button></header><div class="battle-hud" id="battle-hud"></div><div class="canvas-wrap"><canvas id="battle-canvas" aria-label="${dungeon.name}竖屏侧视战斗"></canvas><div class="battle-guide" id="battle-guide"><span id="battle-guide-text"></span><button id="close-battle-guide" aria-label="关闭战斗引导">×</button></div></div><div class="touch-controls"><div><button data-control="left" aria-label="向左">◀</button><button data-control="right" aria-label="向右">▶</button></div><div><button data-control="heal" ${poisonBlockedAttr()}>回春丹</button><button data-control="dodge">闪避</button>${state.skillLoadout.map(k=>`<button data-control="skill-${k}">${SKILLS[k].name}<small> ${SKILLS[k].mana}法力</small></button>`).join('')}<button data-control="mana" ${poisonBlockedAttr()}>回灵丹</button><button data-control="attack">攻击</button><button data-control="jump">跳跃</button></div></div><div class="battle-help">${state.toxin>=100?'丹毒已满，无法服用丹药，返回后休养可降低丹毒。':'点击技能释放 · 五行克制伤害×2 · 丹毒共用'}</div></div>`;
  battle=startBattle(document.querySelector('canvas'),state,result=>{battle=null;if(act('return',result)){const r=state.lastExpedition;showModal(r.defeated?'重伤归来':r.cleared?'青岚兽王已败':'平安归来','气血已恢复至满值。带回：'+(Object.entries(r.loot).filter(([,n])=>n>0).map(([id,n])=>ITEMS[id].name+'×'+n).join('、')||'暂无')+'；消耗丹药：'+(r.usedPills.map(p=>ITEMS[p.id].name+'×'+p.qty).join('、')||'无')+'；'+(r.sweepUnlocked?'已解锁一次扫荡，使用后七日恢复。'+(r.dungeon==='qinglan'?'青岚残卷：凝露丹方已解锁；月华种子需灵土。':''):'尚未通关，继续探索。'));}},h=>{const el=document.querySelector('#battle-hud');if(el)el.innerHTML=`<span>气血 <b>${Math.ceil(h.hp)}/${h.maxHP}</b></span><span>法力 <b>${Math.ceil(h.mana)}/${h.maxMana}</b></span>${resourceMeter('丹毒',h.toxin,100,'toxin')}<span>${ITEMS[h.healItem??'heal'].name} <b>${h.heal}</b></span><span>${h.doubleJump?'御风步 · 二段跳':'尚未领悟御风步'}</span><span>战利品 ${Object.values(h.loot).reduce((a,b)=>a+b,0)}</span>`;const guide=document.querySelector('#battle-guide');document.querySelectorAll('[data-control="heal"],[data-control="mana"]').forEach(button=>{button.disabled=h.toxin>=100;button.title=h.toxin>=100?'丹毒已满，无法服丹':'';});const battleHelp=document.querySelector('.battle-help');if(battleHelp)battleHelp.textContent=h.toxin>=100?'丹毒已满，无法服用丹药，返回后休养可降低丹毒。':'点击技能释放 · 五行克制伤害×2 · 丹毒共用';if(guide){guide.hidden=!h.hint;document.querySelector('#battle-guide-text').textContent=h.hint;}},dungeon,event=>{playSound(event.type==='hit'||event.type==='damage'?'hit':'attack');});
  document.querySelector('#close-battle-guide').onclick=()=>{state=transition(state,'toggle-battle-hints');save();battle?.setHints(false);document.querySelector('#battle-guide').hidden=true;};
  document.querySelector('#retreat').onclick=()=>battle?.retreat();
  document.querySelectorAll('[data-control]').forEach(el=>{if(el.dataset.control.startsWith('skill-')){el.addEventListener('click',()=>{battle?.press(el.dataset.control);battle?.release(el.dataset.control);});return;}el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);battle?.press(el.dataset.control);});['pointerup','pointercancel','lostpointercapture'].forEach(type=>el.addEventListener(type,()=>battle?.release(el.dataset.control)));});
}
document.addEventListener('click',e=>{setSound(state.settings.sound);unlockAudio();playSound('click');
  const modal=e.target.closest('[data-modal]');if(modal){if(modal.dataset.modal==='hints'){act('toggle-battle-hints');document.querySelector('.modal')?.remove();}else if(modal.dataset.modal==='sound'){act('toggle-sound');document.querySelector('.modal')?.remove();}else if(modal.dataset.modal==='restart')restart();else if(modal.dataset.modal==='confirm-reset')showModal('重新开始？','将清除当前存档，回到炼气五级与初始资产。',[['重新开始','restart'],['保留存档','close']]);else if(modal.dataset.modal==='help')showModal('山居入门','点击药田播种，休息两日收草交订单。破败丹炉可炼粗制丹药，升级后可炼更高品质。每80修为突破一级，炼气十级后筑基解锁御剑。十个秘境按等级依次解锁，出发前带好回春丹。每30日催债，留一些灵草备用。');else document.querySelector('.modal')?.remove();return;}
  const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();
  const action=el.dataset.action;
  if(action==='iso-edit'){beginHomeEdit();return;}
  if(action==='iso-restore'){homeEdit.tool='move';homeEdit.selected=el.dataset.object;render();return;}
  if(action==='iso-tool'){homeEdit.tool=el.dataset.tool;homeEdit.selected=null;render();return;}
  if(action==='iso-cancel'){homeEdit=null;render();return;}
  if(action==='iso-save'){const layout=homeEdit.layout;if(act('save-home-layout',{layout})){homeEdit=null;render();toast('布置已保存');}return;}
  if(action==='iso-object'){const o=state.homeLayout.objects.find(o=>o.id===el.dataset.object);if(o.kind==='plot')openPlot(o.index);else{page=o.kind==='house'?'home':'alchemy';render();}return;}
  if(action==='story'){const id=el.dataset.id??pendingStory(state);if(id)openSheet('山居来信',storyPanel(id));else openSheet('任务',questPanel());return;}
  if(action==='story-go'){if(act('read-story',{id:el.dataset.id})){document.querySelector('.modal')?.remove();page=el.dataset.page;render();}return;}
  if(action==='read-story'){if(act('read-story',{id:el.dataset.id}))document.querySelector('.modal')?.remove();return;}
  if(action==='farm-panel'){openSheet('药田',farmPanel().replace(scene(true),''));return;}
  if(action==='bag-item'){bagSelected={id:el.dataset.item,kind:el.dataset.kind};openSheet('物品详情',bagDetail());return;}
  if(action==='quest-tab'){questTab=el.dataset.filter;openSheet('任务',questPanel());return;}
  if(action==='chapter-panel'){questTab='ongoing';openSheet('任务',questPanel());return;}
  if(action==='home-panel'){openSheet('住宅',homeControls());return;}
  if(action==='home-warehouse'){syncLayout(state);openSheet('家园仓库',homeWarehousePanel());return;}
  if(action==='home-place-object'){const id=el.dataset.object;document.querySelector('.modal')?.remove();homeEdit={layout:structuredClone(state.homeLayout),selected:id,tool:'move'};render();return;}
  if(action==='notice-panel'){openSheet('催债提醒',state.notices.map(n=>'<p>'+n.text+'</p>'+button('知道了','dismiss-notice','data-day="'+n.day+'"')).join('')||'<p>'+nextCollectionText()+'</p>');return;}
  if(action==='shop-grade'){shopGrade=Number(el.dataset.grade);render();return;}
  if(action==='shop-tab'){shopTab=el.dataset.filter;render();return;}
  if(action==='foundation-shop'){shopTab='pills';shopGrade=ITEMS.foundationPill.grade;page='shop';render();return;}
  if(action==='warehouse-tab'){warehouseTab=el.dataset.filter;render();return;}
  if(action==='recipe-grade'){recipeGrade=Number(el.dataset.grade);render();return;}
  if(action==='equipment-slot'){openEquipment(el.dataset.slot);return;}
  if(action==='expand-menu'){openExpansion();return;}
  if(action==='soil-menu'){openPlot(Number(el.dataset.index),'soil');return;}
  if(action==='plot-page'){farmPage=Math.max(0,Math.min(Math.ceil(state.plots.length/4)-1,Number(el.dataset.fieldPage)));render();return;}
  if(action==='plot'){openPlot(Number(el.dataset.index));return;}
  if(action==='navigate'){homeEdit=null;document.querySelector('.modal')?.remove();page=el.dataset.page;render();return;}
  if(action==='select-dungeon'){selectedDungeon=el.dataset.dungeon;render();return;}
  if(action==='menu'){showModal('山居菜单','存档自动保存在当前浏览器。离线不推进时间。',[[state.settings.sound?'关闭音效':'开启音效','sound'],[state.settings.battleHints?'关闭战斗提示':'开启战斗提示','hints'],['玩法说明','help'],['重新开始','confirm-reset'],['返回游戏','close']]);return;}
  if(action==='reset'){showModal('重新开始？','将清除当前存档，回到炼气五级、500灵石与100万欠款的开局。',[['重新开始','restart'],['保留存档','close']]);return;}
  if(action==='help'){showModal('山居入门','先播种，再休养两日，收草交订单。破败丹炉可直接炼粗制丹药，花灵石升级后解锁更高品质。修炼与服丹积累修为，每80修为突破一级，炼气十级后突破筑基。筑基解锁秘境，带上回春丹再出发。每30日债主计息催收；保留一些仙草，避免现金与草药同时耗尽。MVP已加快成长，数值尚待平衡。');return;}
  if(action==='enter'){enter(el.dataset.dungeon??selectedDungeon);return;}
  const succeeded=act(action,{day:Number(el.dataset.day),slot:el.dataset.slot,dungeonId:el.dataset.dungeon,crop:el.dataset.crop,seed:document.querySelector('select[data-seed-for="'+el.dataset.crop+'"]')?.value,soil:el.dataset.soil,item:el.dataset.item,index:el.dataset.index===undefined?undefined:Number(el.dataset.index),id:el.dataset.id,qty:el.dataset.qty===undefined?undefined:Number(el.dataset.qty),amount:Number(document.querySelector('#amount')?.value)});
  if(succeeded && ['plant','harvest','soil','expand-plot','equip','unequip'].includes(action))document.querySelector('.modal')?.remove();
  if(succeeded && action==='expand-plot'){farmPage=Math.floor((state.plots.length-1)/4);page='farm';render();}
});
window.addEventListener('pagehide',()=>{battle?.retreat();save();});
